"""Installer for PR (Phase 7): Multi-Backend Isolated Terminal Engine & Sandboxing System.

Implements dream.terminal with support for Local Hardened Runner, Docker Container Sandbox,
SSH Remote Runner, 5-layer Security Blocklist enforcement, dynamic switching, and tool calling.
"""

import os
import subprocess
import sys
from pathlib import Path

