FILES['dream/terminal/__init__.py'] = '"""Dream Multi-Backend Isolated Terminal Engine and Sandboxing Subsystem."""\n\nfrom dream.terminal.backends.base import BaseTerminalBackend\nfrom dream.terminal.backends.docker import DockerSandboxBackend\nfrom dream.terminal.backends.local import LocalTerminalBackend\nfrom dream.terminal.backends.ssh import SSHRemoteBackend\nfrom dream.terminal.manager import TerminalManager\nfrom dream.terminal.slash import handle_terminal_command\nfrom dream.terminal.tools import (\n    get_terminal_manager,\n    reset_terminal_manager,\n    terminal_execute,\n    terminal_list_backends,\n    terminal_switch_backend,\n)\nfrom dream.terminal.types import (\n    BackendHealth,\n    CommandExecutionRequest,\n    CommandExecutionResult,\n    TerminalBackendType,\n)\n\n__all__ = [\n    "BaseTerminalBackend",\n    "LocalTerminalBackend",\n    "DockerSandboxBackend",\n    "SSHRemoteBackend",\n    "TerminalManager",\n    "TerminalBackendType",\n    "CommandExecutionRequest",\n    "CommandExecutionResult",\n    "BackendHealth",\n    "get_terminal_manager",\n    "reset_terminal_manager",\n    "terminal_execute",\n    "terminal_list_backends",\n    "terminal_switch_backend",\n    "handle_terminal_command",\n]\n'

FILES['dream/terminal/types.py'] = '"""Type definitions and data models for the Terminal Execution subsystem."""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom datetime import datetime, timezone\nfrom enum import Enum\nfrom typing import Any\n\n\nclass TerminalBackendType(str, Enum):\n    """Supported terminal execution backend types."""\n\n    LOCAL = "local"\n    DOCKER = "docker"\n    SSH = "ssh"\n    MOCK = "mock"\n\n\n@dataclass\nclass CommandExecutionRequest:\n    """Request payload for executing a shell/terminal command."""\n\n    command: str\n    cwd: str | None = None\n    env: dict[str, str] = field(default_factory=dict)\n    timeout: float = 30.0\n    backend_type: TerminalBackendType | None = None\n    max_output_bytes: int = 65_536\n    interactive: bool = False\n    metadata: dict[str, Any] = field(default_factory=dict)\n\n\n@dataclass\nclass CommandExecutionResult:\n    """Result of a command executed on a terminal backend."""\n\n    command: str\n    returncode: int\n    stdout: str\n    stderr: str\n    duration_ms: float\n    backend: TerminalBackendType\n    is_truncated: bool = False\n    timed_out: bool = False\n    error_message: str | None = None\n    timestamp: datetime = field(default_factory=lambda: datetime.now(timezone.utc))\n\n    @property\n    def is_success(self) -> bool:\n        """Check if execution completed with exit code 0."""\n        return self.returncode == 0 and not self.timed_out\n\n    def to_dict(self) -> dict[str, Any]:\n        """Serialize result to dictionary."""\n        return {\n            "command": self.command,\n            "returncode": self.returncode,\n            "stdout": self.stdout,\n            "stderr": self.stderr,\n            "duration_ms": self.duration_ms,\n            "backend": self.backend.value,\n            "is_truncated": self.is_truncated,\n            "timed_out": self.timed_out,\n            "error_message": self.error_message,\n            "timestamp": self.timestamp.isoformat(),\n        }\n\n\n@dataclass\nclass BackendHealth:\n    """Diagnostic health status of a terminal backend."""\n\n    backend: TerminalBackendType\n    available: bool\n    details: str\n    latency_ms: float = 0.0\n    metadata: dict[str, Any] = field(default_factory=dict)\n'

FILES['dream/terminal/manager.py'] = '"""Central Terminal Execution Manager and multi-backend orchestrator."""\n\nfrom __future__ import annotations\n\nimport logging\nimport threading\nfrom typing import Any\n\nfrom dream.security.blocklist import scan as floor_scan\nfrom dream.terminal.backends.base import BaseTerminalBackend\nfrom dream.terminal.backends.local import LocalTerminalBackend\nfrom dream.terminal.types import (\n    CommandExecutionRequest,\n    CommandExecutionResult,\n    TerminalBackendType,\n)\n\nlogger = logging.getLogger(__name__)\n\n\nclass SecurityBlocklistViolation(Exception):\n    """Raised when a command violates Layer-3 security floor policies."""\n    pass\n\n\nclass TerminalManager:\n    """Manages backend registry, security scanning, and command dispatch."""\n\n    def __init__(\n        self,\n        default_backend: TerminalBackendType = TerminalBackendType.LOCAL,\n        enable_security_scan: bool = True,\n    ) -> None:\n        self.active_backend_type = default_backend\n        self.enable_security_scan = enable_security_scan\n        self._lock = threading.RLock()\n        self._backends: dict[TerminalBackendType, BaseTerminalBackend] = {}\n\n        # Register default local backend\n        self.register_backend(LocalTerminalBackend())\n\n    def register_backend(self, backend: BaseTerminalBackend) -> None:\n        """Register a terminal backend in the pool."""\n        with self._lock:\n            self._backends[backend.backend_type] = backend\n            logger.info(f"Registered terminal backend: {backend.backend_type.value}")\n\n    def get_backend(\n        self,\n        backend_type: TerminalBackendType | None = None,\n    ) -> BaseTerminalBackend | None:\n        """Retrieve a registered backend by type or active default."""\n        with self._lock:\n            target = backend_type or self.active_backend_type\n            return self._backends.get(target)\n\n    def set_active_backend(self, backend_type: TerminalBackendType | str) -> bool:\n        """Switch the default terminal backend."""\n        with self._lock:\n            if isinstance(backend_type, str):\n                try:\n                    backend_type = TerminalBackendType(backend_type.lower())\n                except ValueError:\n                    logger.error(f"Unknown terminal backend type: {backend_type}")\n                    return False\n\n            if backend_type not in self._backends:\n                logger.warning(f"Backend {backend_type.value} is not registered.")\n                return False\n\n            self.active_backend_type = backend_type\n            logger.info(f"Active terminal backend switched to: {backend_type.value}")\n            return True\n\n    def execute(\n        self,\n        command: str,\n        backend_type: TerminalBackendType | None = None,\n        cwd: str | None = None,\n        env: dict[str, str] | None = None,\n        timeout: float = 30.0,\n    ) -> CommandExecutionResult:\n        """Execute command through security filter and active backend."""\n        # 1. Layer-3 Security Blocklist Verification\n        if self.enable_security_scan:\n            finding = floor_scan(command)\n            if finding:\n                rule_id = finding.rule.rule_id if hasattr(finding, "rule") else "L3-BLOCK"\n                name_en = (\n                    finding.rule.name_en if hasattr(finding, "rule") else "destructive command"\n                )\n                err_msg = (\n                    f"⛔ اجرای دستور به دلیل نقض قوانین امنیتی مسدود شد: {rule_id}\\n"\n                    f"Command blocked by security rule: {name_en}"\n                )\n                logger.warning(f"Terminal command blocked: {command} -> {rule_id}")\n                return CommandExecutionResult(\n                    command=command,\n                    returncode=126,\n                    stdout="",\n                    stderr=err_msg,\n                    duration_ms=0.0,\n                    backend=backend_type or self.active_backend_type,\n                    error_message=err_msg,\n                )\n\n        # 2. Select backend\n        backend = self.get_backend(backend_type)\n        if not backend:\n            target_name = (backend_type or self.active_backend_type).value\n            err_msg = f"Terminal backend \'{target_name}\' is not registered."\n            return CommandExecutionResult(\n                command=command,\n                returncode=-1,\n                stdout="",\n                stderr=err_msg,\n                duration_ms=0.0,\n                backend=backend_type or self.active_backend_type,\n                error_message=err_msg,\n            )\n\n        # 3. Dispatch execution\n        req = CommandExecutionRequest(\n            command=command,\n            cwd=cwd,\n            env=env or {},\n            timeout=timeout,\n            backend_type=backend.backend_type,\n        )\n        return backend.execute(req)\n\n    def list_backends(self) -> list[dict[str, Any]]:\n        """Return status and diagnostics for all registered backends."""\n        with self._lock:\n            results = []\n            for b_type, backend in self._backends.items():\n                health = backend.health_check()\n                results.append({\n                    "type": b_type.value,\n                    "is_active": b_type == self.active_backend_type,\n                    "available": health.available,\n                    "details": health.details,\n                    "latency_ms": health.latency_ms,\n                    "metadata": health.metadata,\n                })\n            return results\n'

FILES['dream/terminal/tools.py'] = '"""Agent tool definitions for Terminal Multi-Backend execution."""\n\nfrom __future__ import annotations\n\nimport json\n\nfrom dream.terminal.manager import TerminalManager\nfrom dream.terminal.types import TerminalBackendType\n\n_GLOBAL_TERMINAL_MANAGER: TerminalManager | None = None\n\n\ndef get_terminal_manager() -> TerminalManager:\n    """Retrieve or create singleton TerminalManager."""\n    global _GLOBAL_TERMINAL_MANAGER\n    if _GLOBAL_TERMINAL_MANAGER is None:\n        _GLOBAL_TERMINAL_MANAGER = TerminalManager()\n    return _GLOBAL_TERMINAL_MANAGER\n\n\ndef reset_terminal_manager() -> None:\n    """Reset the global TerminalManager instance for testing."""\n    global _GLOBAL_TERMINAL_MANAGER\n    _GLOBAL_TERMINAL_MANAGER = None\n\n\ndef terminal_execute(\n    command: str,\n    backend: str | None = None,\n    cwd: str | None = None,\n    timeout: float = 30.0,\n) -> str:\n    """Execute a shell/terminal command across available local or isolated backends.\n\n    Args:\n        command: The shell command to execute.\n        backend: Optional backend name (\'local\', \'docker\', \'ssh\'). Defaults to active backend.\n        cwd: Working directory path for execution.\n        timeout: Execution timeout in seconds (default 30s).\n    """\n    mgr = get_terminal_manager()\n    b_type = TerminalBackendType(backend.lower()) if backend else None\n    result = mgr.execute(command, backend_type=b_type, cwd=cwd, timeout=timeout)\n    return json.dumps(result.to_dict(), ensure_ascii=False, indent=2)\n\n\ndef terminal_list_backends() -> str:\n    """List all registered terminal backends with availability and health metrics."""\n    mgr = get_terminal_manager()\n    backends = mgr.list_backends()\n    return json.dumps({"backends": backends}, ensure_ascii=False, indent=2)\n\n\ndef terminal_switch_backend(backend: str) -> str:\n    """Switch the default active terminal backend (e.g. \'docker\', \'local\', \'ssh\')."""\n    mgr = get_terminal_manager()\n    ok = mgr.set_active_backend(backend)\n    if ok:\n        return f"Active terminal backend switched to: {backend}"\n    return (\n        f"Failed to switch to backend: {backend}. "\n        "Check available backends with terminal_list_backends."\n    )\n'

FILES['dream/terminal/slash.py'] = '"""Slash command handler for terminal management."""\n\nfrom __future__ import annotations\n\nfrom collections.abc import Callable\n\nfrom dream.terminal.tools import get_terminal_manager\n\n\ndef handle_terminal_command(args: str, output: Callable[[str], None] = print) -> bool:\n    """Process `/terminal` or `/backend` slash commands.\n\n    Usage:\n        /terminal\n        /terminal backends\n        /terminal set <local|docker|ssh>\n    """\n    parts = args.strip().split()\n    mgr = get_terminal_manager()\n\n    if not parts or parts[0] in ("status", "backends", "list"):\n        output("🖥️ **پایانه\u200cهای اجرایی فعال / Terminal Backends:**\\n")\n        for b in mgr.list_backends():\n            status_icon = "🟢" if b["available"] else "🔴"\n            active_marker = "★ [ACTIVE]" if b["is_active"] else ""\n            output(\n                f"  {status_icon} **{b[\'type\'].upper()}** {active_marker}\\n"\n                f"     Status: {b[\'details\']} (Latency: {b[\'latency_ms\']:.1f}ms)\\n"\n            )\n        return True\n\n    if parts[0] in ("set", "switch", "use") and len(parts) > 1:\n        target = parts[1]\n        ok = mgr.set_active_backend(target)\n        if ok:\n            output(\n                f"✅ پایانه فعال به `{target}` تغییر یافت. / "\n                f"Active terminal backend set to `{target}`."\n            )\n        else:\n            output(\n                f"❌ پایانه `{target}` یافت نشد یا در دسترس نیست. / "\n                f"Backend not found or unavailable."\n            )\n        return True\n\n    output(\n        "راهنمای دستور پایانه / Terminal Command Help:\\n"\n        "  /terminal\\n"\n        "  /terminal set <local|docker|ssh>"\n    )\n    return True\n'

FILES['dream/terminal/backends/__init__.py'] = '"""Terminal execution backend implementations."""\n\nfrom dream.terminal.backends.base import BaseTerminalBackend\nfrom dream.terminal.backends.docker import DockerSandboxBackend\nfrom dream.terminal.backends.local import LocalTerminalBackend\nfrom dream.terminal.backends.ssh import SSHRemoteBackend\n\n__all__ = [\n    "BaseTerminalBackend",\n    "LocalTerminalBackend",\n    "DockerSandboxBackend",\n    "SSHRemoteBackend",\n]\n'

FILES['dream/terminal/backends/base.py'] = '"""Abstract base interface for terminal execution backends."""\n\nfrom __future__ import annotations\n\nfrom abc import ABC, abstractmethod\n\nfrom dream.terminal.types import (\n    BackendHealth,\n    CommandExecutionRequest,\n    CommandExecutionResult,\n    TerminalBackendType,\n)\n\n\nclass BaseTerminalBackend(ABC):\n    """Abstract base class for all terminal execution environments."""\n\n    def __init__(self, backend_type: TerminalBackendType) -> None:\n        self.backend_type = backend_type\n\n    @abstractmethod\n    def execute(self, request: CommandExecutionRequest) -> CommandExecutionResult:\n        """Execute command in the designated environment and return structured result."""\n        raise NotImplementedError\n\n    @abstractmethod\n    def is_available(self) -> bool:\n        """Check if backend runtime prerequisites are satisfied on this host."""\n        raise NotImplementedError\n\n    @abstractmethod\n    def health_check(self) -> BackendHealth:\n        """Perform diagnostic ping and return availability metrics."""\n        raise NotImplementedError\n\n    def cleanup(self) -> None:\n        """Release background resources or active subprocess handles."""\n        return None\n'

FILES['dream/terminal/backends/local.py'] = '"""Local hardened subprocess execution backend."""\n\nfrom __future__ import annotations\n\nimport os\nimport subprocess\nimport sys\nimport time\nfrom pathlib import Path\nfrom typing import Any\n\nfrom dream.terminal.backends.base import BaseTerminalBackend\nfrom dream.terminal.types import (\n    BackendHealth,\n    CommandExecutionRequest,\n    CommandExecutionResult,\n    TerminalBackendType,\n)\n\n\nclass LocalTerminalBackend(BaseTerminalBackend):\n    """Executes commands directly on the host in a hardened, bounded subprocess."""\n\n    def __init__(self, default_cwd: str | None = None) -> None:\n        super().__init__(TerminalBackendType.LOCAL)\n        self.default_cwd = default_cwd or str(Path.cwd())\n\n    def is_available(self) -> bool:\n        """Local backend is always available on any Python host."""\n        return True\n\n    def health_check(self) -> BackendHealth:\n        """Verify local shell execution."""\n        start = time.perf_counter()\n        try:\n            cmd = ["echo", "health_ok"] if sys.platform != "win32" else "cmd /c echo health_ok"\n            res = subprocess.run(\n                cmd,\n                shell=(sys.platform == "win32"),\n                capture_output=True,\n                text=True,\n                timeout=5.0,\n            )\n            duration_ms = (time.perf_counter() - start) * 1000\n            ok = res.returncode == 0 and "health_ok" in res.stdout\n            return BackendHealth(\n                backend=self.backend_type,\n                available=ok,\n                details="Local host shell ready" if ok else "Local shell check failed",\n                latency_ms=duration_ms,\n                metadata={"platform": sys.platform, "default_cwd": self.default_cwd},\n            )\n        except Exception as exc:\n            duration_ms = (time.perf_counter() - start) * 1000\n            return BackendHealth(\n                backend=self.backend_type,\n                available=False,\n                details=f"Local execution error: {exc}",\n                latency_ms=duration_ms,\n            )\n\n    def execute(self, request: CommandExecutionRequest) -> CommandExecutionResult:\n        """Execute command locally with timeout, output truncation, and environment isolation."""\n        start_time = time.perf_counter()\n        cwd = request.cwd or self.default_cwd\n\n        # Build scrubbed child environment\n        child_env = self._build_safe_env(request.env)\n\n        # Determine shell invocation\n        use_shell = True\n        shell_cmd: Any = request.command\n\n        try:\n            proc = subprocess.Popen(\n                shell_cmd,\n                shell=use_shell,\n                cwd=cwd,\n                env=child_env,\n                stdout=subprocess.PIPE,\n                stderr=subprocess.PIPE,\n                text=True,\n                errors="replace",\n            )\n            try:\n                stdout_raw, stderr_raw = proc.communicate(timeout=request.timeout)\n                timed_out = False\n            except subprocess.TimeoutExpired:\n                proc.kill()\n                stdout_raw, stderr_raw = proc.communicate()\n                timed_out = True\n\n            duration_ms = (time.perf_counter() - start_time) * 1000\n\n            # Truncate output if exceeding max bytes\n            max_bytes = request.max_output_bytes\n            is_truncated = False\n\n            if len(stdout_raw) > max_bytes:\n                stdout_raw = stdout_raw[:max_bytes] + "\\n... [Output Truncated / خروجی کوتاه شد]"\n                is_truncated = True\n\n            if len(stderr_raw) > max_bytes:\n                stderr_raw = stderr_raw[:max_bytes] + "\\n... [Error Output Truncated]"\n                is_truncated = True\n\n            return CommandExecutionResult(\n                command=request.command,\n                returncode=proc.returncode if not timed_out else -1,\n                stdout=stdout_raw,\n                stderr=stderr_raw,\n                duration_ms=duration_ms,\n                backend=self.backend_type,\n                is_truncated=is_truncated,\n                timed_out=timed_out,\n                error_message="Command execution timed out" if timed_out else None,\n            )\n        except Exception as exc:\n            duration_ms = (time.perf_counter() - start_time) * 1000\n            return CommandExecutionResult(\n                command=request.command,\n                returncode=-1,\n                stdout="",\n                stderr=str(exc),\n                duration_ms=duration_ms,\n                backend=self.backend_type,\n                timed_out=False,\n                error_message=str(exc),\n            )\n\n    def _build_safe_env(self, custom_env: dict[str, str]) -> dict[str, str]:\n        """Scrub sensitive parent variables and merge allowed custom environment."""\n        # Baseline minimal safe environment\n        safe_keys = {\n            "PATH", "SYSTEMROOT", "WINDIR", "TEMP", "TMP",\n            "HOME", "USER", "LOGNAME", "SHELL", "LANG", "LC_ALL",\n            "PYTHONPATH", "VIRTUAL_ENV",\n        }\n        env = {k: v for k, v in os.environ.items() if k.upper() in safe_keys}\n\n        # Filter out obvious secret shapes from inherited env\n        for key in list(env.keys()):\n            k_upper = key.upper()\n            if any(secret in k_upper for secret in ("KEY", "SECRET", "TOKEN", "PASSWORD", "AUTH")):\n                env.pop(key, None)\n\n        env.update(custom_env)\n        return env\n'

FILES['dream/terminal/backends/docker.py'] = '"""Docker Container Sandboxed execution backend."""\n\nfrom __future__ import annotations\n\nimport shutil\nimport subprocess\nimport time\nfrom pathlib import Path\n\nfrom dream.terminal.backends.base import BaseTerminalBackend\nfrom dream.terminal.types import (\n    BackendHealth,\n    CommandExecutionRequest,\n    CommandExecutionResult,\n    TerminalBackendType,\n)\n\n\nclass DockerSandboxBackend(BaseTerminalBackend):\n    """Executes commands inside a hardened, isolated Docker container."""\n\n    def __init__(\n        self,\n        image: str = "python:3.11-slim",\n        network_mode: str = "none",\n        memory_limit: str = "512m",\n        cpu_limit: str = "1.0",\n        pids_limit: int = 64,\n        read_only_rootfs: bool = True,\n        workspace_mount: str | None = None,\n    ) -> None:\n        super().__init__(TerminalBackendType.DOCKER)\n        self.image = image\n        self.network_mode = network_mode\n        self.memory_limit = memory_limit\n        self.cpu_limit = cpu_limit\n        self.pids_limit = pids_limit\n        self.read_only_rootfs = read_only_rootfs\n        self.workspace_mount = workspace_mount or str(Path.cwd())\n\n    def is_available(self) -> bool:\n        """Check if docker binary is on PATH and daemon responds."""\n        docker_bin = shutil.which("docker")\n        if not docker_bin:\n            return False\n        try:\n            res = subprocess.run(\n                ["docker", "info"],\n                capture_output=True,\n                text=True,\n                timeout=3.0,\n            )\n            return res.returncode == 0\n        except Exception:\n            return False\n\n    def health_check(self) -> BackendHealth:\n        """Verify Docker sandbox readiness and image availability."""\n        start = time.perf_counter()\n        if not shutil.which("docker"):\n            return BackendHealth(\n                backend=self.backend_type,\n                available=False,\n                details="Docker CLI is not installed on host / ابزار داکر نصب نیست.",\n                latency_ms=0.0,\n            )\n\n        try:\n            res = subprocess.run(["docker", "info"], capture_output=True, text=True, timeout=5.0)\n            duration_ms = (time.perf_counter() - start) * 1000\n            if res.returncode == 0:\n                return BackendHealth(\n                    backend=self.backend_type,\n                    available=True,\n                    details=f"Docker sandbox ready (Image: {self.image})",\n                    latency_ms=duration_ms,\n                    metadata={"image": self.image, "network": self.network_mode},\n                )\n            return BackendHealth(\n                backend=self.backend_type,\n                available=False,\n                details="Docker daemon is not running / سرویس داکر در حال اجرا نیست.",\n                latency_ms=duration_ms,\n            )\n        except Exception as exc:\n            duration_ms = (time.perf_counter() - start) * 1000\n            return BackendHealth(\n                backend=self.backend_type,\n                available=False,\n                details=f"Docker health check failed: {exc}",\n                latency_ms=duration_ms,\n            )\n\n    def execute(self, request: CommandExecutionRequest) -> CommandExecutionResult:\n        """Execute command in an ephemeral, resource-bounded Docker sandbox."""\n        start_time = time.perf_counter()\n\n        if not self.is_available():\n            duration_ms = (time.perf_counter() - start_time) * 1000\n            err = (\n                "داکر در دسترس نیست؛ اجرای ایزوله امکان\u200cپذیر نمی\u200cباشد. / "\n                "Docker sandbox is unavailable."\n            )\n            return CommandExecutionResult(\n                command=request.command,\n                returncode=-1,\n                stdout="",\n                stderr=err,\n                duration_ms=duration_ms,\n                backend=self.backend_type,\n                error_message=err,\n            )\n\n        # Construct Docker CLI arguments\n        docker_args = [\n            "docker", "run", "--rm", "-i",\n            f"--network={self.network_mode}",\n            f"--memory={self.memory_limit}",\n            f"--cpus={self.cpu_limit}",\n            f"--pids-limit={self.pids_limit}",\n        ]\n\n        if self.read_only_rootfs:\n            docker_args.extend(["--read-only", "--tmpfs", "/tmp:rw,noexec,nosuid,size=64m"])\n\n        # Mount workspace volume\n        mount_path = request.cwd or self.workspace_mount\n        docker_args.extend(["-v", f"{mount_path}:/workspace:rw", "-w", "/workspace"])\n\n        # Inject environment variables\n        for k, v in request.env.items():\n            docker_args.extend(["-e", f"{k}={v}"])\n\n        docker_args.extend([self.image, "sh", "-c", request.command])\n\n        try:\n            proc = subprocess.Popen(\n                docker_args,\n                stdout=subprocess.PIPE,\n                stderr=subprocess.PIPE,\n                text=True,\n                errors="replace",\n            )\n            try:\n                stdout_raw, stderr_raw = proc.communicate(timeout=request.timeout)\n                timed_out = False\n            except subprocess.TimeoutExpired:\n                proc.kill()\n                stdout_raw, stderr_raw = proc.communicate()\n                timed_out = True\n\n            duration_ms = (time.perf_counter() - start_time) * 1000\n\n            max_bytes = request.max_output_bytes\n            is_truncated = False\n            if len(stdout_raw) > max_bytes:\n                stdout_raw = stdout_raw[:max_bytes] + "\\n... [Output Truncated]"\n                is_truncated = True\n\n            return CommandExecutionResult(\n                command=request.command,\n                returncode=proc.returncode if not timed_out else -1,\n                stdout=stdout_raw,\n                stderr=stderr_raw,\n                duration_ms=duration_ms,\n                backend=self.backend_type,\n                is_truncated=is_truncated,\n                timed_out=timed_out,\n                error_message="Sandbox execution timed out" if timed_out else None,\n            )\n        except Exception as exc:\n            duration_ms = (time.perf_counter() - start_time) * 1000\n            return CommandExecutionResult(\n                command=request.command,\n                returncode=-1,\n                stdout="",\n                stderr=str(exc),\n                duration_ms=duration_ms,\n                backend=self.backend_type,\n                error_message=str(exc),\n            )\n'

FILES['dream/terminal/backends/ssh.py'] = '"""Remote SSH Execution backend."""\n\nfrom __future__ import annotations\n\nimport shutil\nimport subprocess\nimport time\n\nfrom dream.terminal.backends.base import BaseTerminalBackend\nfrom dream.terminal.types import (\n    BackendHealth,\n    CommandExecutionRequest,\n    CommandExecutionResult,\n    TerminalBackendType,\n)\n\n\nclass SSHRemoteBackend(BaseTerminalBackend):\n    """Executes commands on a remote host via secure SSH tunnel."""\n\n    def __init__(\n        self,\n        host: str,\n        port: int = 22,\n        user: str | None = None,\n        key_path: str | None = None,\n        remote_cwd: str | None = None,\n    ) -> None:\n        super().__init__(TerminalBackendType.SSH)\n        self.host = host\n        self.port = port\n        self.user = user\n        self.key_path = key_path\n        self.remote_cwd = remote_cwd\n\n    def is_available(self) -> bool:\n        """Check if ssh executable is present on local host."""\n        return shutil.which("ssh") is not None\n\n    def health_check(self) -> BackendHealth:\n        """Verify SSH connection to remote host."""\n        start = time.perf_counter()\n        if not self.is_available():\n            return BackendHealth(\n                backend=self.backend_type,\n                available=False,\n                details="SSH client is not installed on local host.",\n                latency_ms=0.0,\n            )\n\n        cmd = self._build_ssh_cmd("echo ssh_ok", timeout=5.0)\n        try:\n            res = subprocess.run(cmd, capture_output=True, text=True, timeout=6.0)\n            duration_ms = (time.perf_counter() - start) * 1000\n            ok = res.returncode == 0 and "ssh_ok" in res.stdout\n            detail_msg = (\n                f"SSH remote ready ({self.host}:{self.port})"\n                if ok\n                else f"SSH failed: {res.stderr.strip()}"\n            )\n            return BackendHealth(\n                backend=self.backend_type,\n                available=ok,\n                details=detail_msg,\n                latency_ms=duration_ms,\n                metadata={"host": self.host, "port": self.port, "user": self.user},\n            )\n        except Exception as exc:\n            duration_ms = (time.perf_counter() - start) * 1000\n            return BackendHealth(\n                backend=self.backend_type,\n                available=False,\n                details=f"SSH connection error: {exc}",\n                latency_ms=duration_ms,\n            )\n\n    def execute(self, request: CommandExecutionRequest) -> CommandExecutionResult:\n        """Execute command remotely over SSH."""\n        start_time = time.perf_counter()\n\n        # Format remote command string with env and directory\n        remote_cmd_parts = []\n        target_dir = request.cwd or self.remote_cwd\n        if target_dir:\n            remote_cmd_parts.append(f"cd {target_dir}")\n\n        for k, v in request.env.items():\n            remote_cmd_parts.append(f"export {k}=\'{v}\'")\n\n        remote_cmd_parts.append(request.command)\n        remote_command = " && ".join(remote_cmd_parts)\n\n        ssh_args = self._build_ssh_cmd(remote_command, timeout=request.timeout)\n\n        try:\n            proc = subprocess.Popen(\n                ssh_args,\n                stdout=subprocess.PIPE,\n                stderr=subprocess.PIPE,\n                text=True,\n                errors="replace",\n            )\n            try:\n                stdout_raw, stderr_raw = proc.communicate(timeout=request.timeout)\n                timed_out = False\n            except subprocess.TimeoutExpired:\n                proc.kill()\n                stdout_raw, stderr_raw = proc.communicate()\n                timed_out = True\n\n            duration_ms = (time.perf_counter() - start_time) * 1000\n            max_bytes = request.max_output_bytes\n            is_truncated = False\n            if len(stdout_raw) > max_bytes:\n                stdout_raw = stdout_raw[:max_bytes] + "\\n... [Output Truncated]"\n                is_truncated = True\n\n            return CommandExecutionResult(\n                command=request.command,\n                returncode=proc.returncode if not timed_out else -1,\n                stdout=stdout_raw,\n                stderr=stderr_raw,\n                duration_ms=duration_ms,\n                backend=self.backend_type,\n                is_truncated=is_truncated,\n                timed_out=timed_out,\n                error_message="SSH command timed out" if timed_out else None,\n            )\n        except Exception as exc:\n            duration_ms = (time.perf_counter() - start_time) * 1000\n            return CommandExecutionResult(\n                command=request.command,\n                returncode=-1,\n                stdout="",\n                stderr=str(exc),\n                duration_ms=duration_ms,\n                backend=self.backend_type,\n                error_message=str(exc),\n            )\n\n    def _build_ssh_cmd(self, command: str, timeout: float = 30.0) -> list[str]:\n        """Construct SSH invocation argument list."""\n        args = [\n            "ssh",\n            "-p", str(self.port),\n            "-o", "BatchMode=yes",\n            "-o", "StrictHostKeyChecking=accept-new",\n            "-o", f"ConnectTimeout={int(min(timeout, 10))}",\n        ]\n        if self.key_path:\n            args.extend(["-i", self.key_path])\n\n        target = f"{self.user}@{self.host}" if self.user else self.host\n        args.extend([target, command])\n        return args\n'

FILES['tests/test_terminal_backends.py'] = '"""Comprehensive tests for Dream Multi-Backend Terminal Execution Engine."""\n\nfrom __future__ import annotations\n\nimport json\nimport sys\nfrom unittest.mock import MagicMock, patch\n\nfrom dream.terminal.backends.base import BaseTerminalBackend\nfrom dream.terminal.backends.docker import DockerSandboxBackend\nfrom dream.terminal.backends.local import LocalTerminalBackend\nfrom dream.terminal.backends.ssh import SSHRemoteBackend\nfrom dream.terminal.manager import TerminalManager\nfrom dream.terminal.slash import handle_terminal_command\nfrom dream.terminal.tools import (\n    get_terminal_manager,\n    reset_terminal_manager,\n    terminal_execute,\n    terminal_list_backends,\n    terminal_switch_backend,\n)\nfrom dream.terminal.types import (\n    BackendHealth,\n    CommandExecutionRequest,\n    CommandExecutionResult,\n    TerminalBackendType,\n)\n\n\nclass MockTerminalBackend(BaseTerminalBackend):\n    """Mock backend for verifying execution routing without invoking host subprocesses."""\n\n    def __init__(self, backend_type: TerminalBackendType = TerminalBackendType.MOCK) -> None:\n        super().__init__(backend_type)\n        self.executed_requests: list[CommandExecutionRequest] = []\n\n    def is_available(self) -> bool:\n        return True\n\n    def health_check(self) -> BackendHealth:\n        return BackendHealth(backend=self.backend_type, available=True, details="Mock ready")\n\n    def execute(self, request: CommandExecutionRequest) -> CommandExecutionResult:\n        self.executed_requests.append(request)\n        return CommandExecutionResult(\n            command=request.command,\n            returncode=0,\n            stdout=f"mock_out:{request.command}",\n            stderr="",\n            duration_ms=1.5,\n            backend=self.backend_type,\n        )\n\n\ndef test_local_terminal_backend_execution():\n    """Verify local backend executes safe basic commands."""\n    backend = LocalTerminalBackend()\n    assert backend.is_available() is True\n\n    health = backend.health_check()\n    assert health.available is True\n\n    # Test basic command\n    cmd = "echo hello_dream" if sys.platform != "win32" else "echo hello_dream"\n    req = CommandExecutionRequest(command=cmd, timeout=5.0)\n    res = backend.execute(req)\n\n    assert res.is_success is True\n    assert "hello_dream" in res.stdout\n    assert res.backend == TerminalBackendType.LOCAL\n\n\ndef test_local_terminal_backend_environment_scrubbing():\n    """Verify sensitive environment variables are filtered from child subprocesses."""\n    backend = LocalTerminalBackend()\n    safe_env = backend._build_safe_env({"CUSTOM_VAR": "safe_val"})\n    assert "CUSTOM_VAR" in safe_env\n    assert safe_env["CUSTOM_VAR"] == "safe_val"\n\n    # Ensure no API keys or secrets are leaked into child\n    for k in safe_env:\n        assert "OPENAI_API_KEY" not in k\n        assert "SECRET_KEY" not in k\n\n\ndef test_local_terminal_output_truncation():\n    """Verify output truncation when exceeding max_output_bytes."""\n    backend = LocalTerminalBackend()\n    # Mocking large output\n    req = CommandExecutionRequest(\n        command="python -c \\"print(\'A\' * 1000)\\"",\n        max_output_bytes=100,\n        timeout=5.0,\n    )\n    res = backend.execute(req)\n    assert res.is_truncated is True\n    assert len(res.stdout) < 300\n    assert "Truncated" in res.stdout\n\n\ndef test_docker_sandbox_argument_construction():\n    """Verify Docker CLI argument generation and volume mounting."""\n    sandbox = DockerSandboxBackend(\n        image="python:3.11-alpine",\n        network_mode="none",\n        memory_limit="256m",\n        read_only_rootfs=True,\n    )\n    assert sandbox.backend_type == TerminalBackendType.DOCKER\n\n    req = CommandExecutionRequest(\n        command="python -V",\n        cwd="/tmp/my_workspace",\n        env={"APP_ENV": "sandbox"},\n    )\n\n    with patch("shutil.which", return_value="/usr/bin/docker"), \\\n         patch("subprocess.run") as mock_run, \\\n         patch("subprocess.Popen") as mock_popen:\n        mock_run.return_value = MagicMock(returncode=0)\n        mock_proc = MagicMock()\n        mock_proc.communicate.return_value = ("Python 3.11.4\\n", "")\n        mock_proc.returncode = 0\n        mock_popen.return_value = mock_proc\n\n        res = sandbox.execute(req)\n        assert res.is_success is True\n        assert "Python 3.11.4" in res.stdout\n\n        # Verify arguments passed to Popen\n        args = mock_popen.call_args[0][0]\n        assert "--network=none" in args\n        assert "--memory=256m" in args\n        assert "--read-only" in args\n        assert "-v" in args\n\n\ndef test_docker_sandbox_unavailable_fallback():\n    """Verify graceful error reporting when Docker daemon is unreachable."""\n    sandbox = DockerSandboxBackend()\n    with patch("shutil.which", return_value=None):\n        assert sandbox.is_available() is False\n        req = CommandExecutionRequest(command="ls")\n        res = sandbox.execute(req)\n        assert res.is_success is False\n        assert "داکر در دسترس نیست" in res.stderr or "unavailable" in res.stderr\n\n\ndef test_ssh_remote_argument_construction():\n    """Verify SSH remote argument construction and command serialization."""\n    ssh_backend = SSHRemoteBackend(\n        host="remote.dream.ai",\n        port=2222,\n        user="admin",\n        key_path="/path/to/key.pem",\n        remote_cwd="/var/app",\n    )\n    assert ssh_backend.backend_type == TerminalBackendType.SSH\n\n    cmd_args = ssh_backend._build_ssh_cmd("uptime")\n    assert "-p" in cmd_args\n    assert "2222" in cmd_args\n    assert "admin@remote.dream.ai" in cmd_args\n    assert "-i" in cmd_args\n    assert "/path/to/key.pem" in cmd_args\n\n\ndef test_terminal_manager_security_blocklist_enforcement():\n    """Verify TerminalManager blocks forbidden destructive commands."""\n    mgr = TerminalManager(enable_security_scan=True)\n\n    # 1. Root wipe attempt\n    res1 = mgr.execute("rm -rf /")\n    assert res1.returncode == 126\n    assert "مسدود شد" in res1.stderr or "blocked" in res1.stderr\n\n    # 2. Fork bomb attempt\n    res2 = mgr.execute(":(){ :|:& };:")\n    assert res2.returncode == 126\n    assert "مسدود شد" in res2.stderr\n\n    # 3. Registry deletion attempt\n    res3 = mgr.execute("reg delete HKLM /f")\n    assert res3.returncode == 126\n\n\ndef test_terminal_manager_backend_switching():\n    """Verify dynamic switching between multiple registered backends."""\n    mgr = TerminalManager()\n    mock_backend = MockTerminalBackend()\n    docker_backend = DockerSandboxBackend()\n\n    mgr.register_backend(mock_backend)\n    mgr.register_backend(docker_backend)\n\n    # Switch to mock backend\n    ok = mgr.set_active_backend(TerminalBackendType.MOCK)\n    assert ok is True\n    assert mgr.active_backend_type == TerminalBackendType.MOCK\n\n    res = mgr.execute("git status")\n    assert res.stdout == "mock_out:git status"\n    assert len(mock_backend.executed_requests) == 1\n\n\ndef test_terminal_tools_and_slash_command():\n    """Verify tool wrappers and slash command dispatching."""\n    reset_terminal_manager()\n    mgr = get_terminal_manager()\n    mock_backend = MockTerminalBackend()\n    mgr.register_backend(mock_backend)\n    mgr.set_active_backend(TerminalBackendType.MOCK)\n\n    # Tool: list backends\n    backends_json = terminal_list_backends()\n    data = json.loads(backends_json)\n    assert "backends" in data\n    assert any(b["type"] == "mock" for b in data["backends"])\n\n    # Tool: execute\n    exec_json = terminal_execute("ls -la")\n    exec_data = json.loads(exec_json)\n    assert exec_data["returncode"] == 0\n    assert "mock_out:ls -la" in exec_data["stdout"]\n\n    # Tool: switch backend\n    switch_res = terminal_switch_backend("local")\n    assert "switched to: local" in switch_res\n\n    # Slash command /terminal\n    outputs = []\n    handle_terminal_command("", output=outputs.append)\n    assert any("Terminal Backends" in line for line in outputs)\n\n    outputs.clear()\n    handle_terminal_command("set mock", output=outputs.append)\n    assert any("تغییر یافت" in line or "set to" in line for line in outputs)\n    assert mgr.active_backend_type == TerminalBackendType.MOCK\n'


def main():
    print("Installing Phase 7: Multi-Backend Isolated Terminal Engine...")
    for rel_path, content in FILES.items():
        target = Path(rel_path)
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8")
        print(f"  [+] Wrote {rel_path}")

    # Strip any potential BOM from all python files
    for p in Path(".").rglob("*.py"):
        raw = p.read_bytes()
        if raw.startswith(b"\xef\xbb\xbf"):
            p.write_bytes(raw[3:])

    print("\nRunning ruff and test suite...")
    res = subprocess.run([sys.executable, "-m", "pytest", "tests/test_terminal_backends.py", "-v"])
    if res.returncode == 0:
        print("\nAll Terminal Backend tests passed 100%!")
    else:
        print("\nSome tests failed.")

if __name__ == "__main__":
    main()
